from taf.internal.sbts.admin.exceptions import AdminApiProcedureFailureException

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_step, log_result
from taf.rfrl.procedures.resources.python.delta_configurator.core.delta import DeltaOperator
from taf.rfrl.procedures.resources.python.hw_info.hw_info import get_mrbts_id
from taf.rfrl.procedures.resources.python.delta_configurator.exceptions import \
    IncorrectMonitoringIntervalValue


@log_input_and_output
def add_rfthld_moc_via_delta_recommissioning():
    """
    Adds RFTHLD ManagedObject via delta recommissioning, creating dynamically structure with default values.
    TEST ManagedObject and RFTHLD ManagedObject should not be present in uploaded configuration on BTS as it may
    cause in failure due to NIDD validation as objects would have already existed.
    """
    delta = DeltaOperator()
    mrbts_id = get_mrbts_id()

    rfthld_params = {
        "rFPowerErrorHighThreshold": "80",
        "rFPowerErrorLowThreshold": "-80",
        "rfTemperatureHighThreshold": "80",
        "rfTemperatureLowThreshold": "-5",
        "rxAntennaRTWPHighThreshold": "-300",
        "rxAntennaRTWPLowThreshold": "-1100",
        "txAntennaVSWRHighThreshold": "30",
        "rxAntennaRSSIHighThreshold": "-300",
        "rxAntennaRSSILowThreshold": "-1100",
    }

    delta.add_moc_to_delta(dist_name="MRBTS-{0}/MNL-1/MNLENT-1/TEST-1".format(mrbts_id))
    delta.add_moc_to_delta(
        dist_name="MRBTS-{0}/MNL-1/MNLENT-1/TEST-1/RFTHLD-1".format(mrbts_id)
    )

    delta.add_parameters_to_delta(
        dist_name="MRBTS-{0}/MNL-1/MNLENT-1/TEST-1/RFTHLD-1".format(mrbts_id),
        delta_dict=rfthld_params,
    )

    try:
        delta.perform_delta_recommissioning()
    finally:
        delta.remove_delta()


@log_input_and_output
def remove_test_moc_via_delta_recommissioning():
    """
    Removes TEST ManagedObject with all sub-objects inside via delta recommissioning.
    """
    delta = DeltaOperator()
    mrbts_id = get_mrbts_id()

    delta.add_moc_removal_to_delta(
        dist_name="MRBTS-{0}/MNL-1/MNLENT-1/TEST-1".format(mrbts_id)
    )

    try:
        delta.perform_delta_recommissioning()
    finally:
        delta.remove_delta()


@log_input_and_output
def change_act_power_meter_via_delta_recommissioning(value):
    """
    Changes actPowerMeter parameter to desired value in order to enable or disable
    energy monitoring in Real-Time measurements in WebEM.
    """
    delta = DeltaOperator()
    mrbts_id = get_mrbts_id()

    log_step(
        "Setting actPowerMeter to {} value via delta commissioning on BTS".format(value)
    )

    delta.add_parameter_to_delta(
        dist_name="MRBTS-{}/MNL-1/MNLENT-1/FEATCADM-1".format(mrbts_id),
        parameter="actPowerMeter",
        value=value,
    )

    delta.perform_delta_recommissioning()
    log_result("actPowerMeter parameter has been successfully set!")


@log_input_and_output
def change_energy_monitoring_interval_via_delta_recommissioning(monitoring_interval,
                                                                interval_parameters=None):
    """
    Changes mtSBTSRfmEnergyMonitoring, mtSBTSSmEnergyMonitoring and mtBtsEnergyMonitoring
    parameter to desired value in order to set the interval time between collecting BTS counters
    concerning energy monitoring (M40003C0 - M40003C5)

    :param monitoring_interval: time interval between collection of PM counters.
    Possible values: 1440min, 720min, 360min, 60min, 30min, 15min, disabled
    :type monitoring_interval: str

    :param interval_parameters: list of parameters for which the interval will be changed
    (None by default which will be translated to ['mtSBTSRfmEnergyMonitoring'])
    :type interval_parameters: list(str)

    """
    if interval_parameters is None:
        interval_parameters = ['mtSBTSRfmEnergyMonitoring']

    possible_intervals = ['1440min', '720min', '360min', '60min', '30min', '15min', 'disabled']
    if monitoring_interval not in possible_intervals:
        raise IncorrectMonitoringIntervalValue("Incorrect monitoring_interval value given: {0}"
                                               " Possible values: {1}".format(monitoring_interval, possible_intervals))

    _recommission_interval_parameters(interval_parameters=interval_parameters, monitoring_interval=monitoring_interval)
    log_result("{} parameters have been successfully set!".format(interval_parameters))


@log_input_and_output
def _recommission_interval_parameters(interval_parameters, monitoring_interval):
    delta = DeltaOperator()
    mrbts_id = get_mrbts_id()

    log_step(
        "Setting {0} to {1} value via delta commissioning on BTS".format(interval_parameters, monitoring_interval)
    )

    for parameter in interval_parameters:
        delta.add_parameter_to_delta(
            dist_name="MRBTS-{}/MNL-1/MNLENT-1/PMMNL-1".format(mrbts_id),
            parameter=parameter,
            value=monitoring_interval,
        )

    delta.perform_delta_recommissioning()
    log_result("{} parameters have been succesfully set!".format(interval_parameters))


@log_input_and_output
def set_parameter_via_delta_recommissioning(dist_name, parameter, value, timeout=120,
                                            skip_parameter_relation_errors=False):
    """
    Sets parameter on commissioned BTS via BTS delta recommissioning procedure.

    :param dist_name: Dist name to Manage Object with desired parameter.
    :type dist_name: str
    :param parameter: Parameter abbreviation that user wants to change.
    :param value: new value of parameter to be set via BTS delta recommissioning.
    :type value: str
    :param timeout: time in seconds to wait for successful recommissioning, defaults to 120
    :type timeout: int
    :param skip_parameter_relation_errors: Skip parameter relation errors.
    :type skip_parameter_relation_errors: boolean
    """
    delta = DeltaOperator()
    log_step(
        "Setting {0} to {1} value via delta commissioning on BTS".format(
            parameter, value
        )
    )

    delta.add_parameter_to_delta(dist_name=dist_name, parameter=parameter, value=value)
    delta.perform_delta_recommissioning(timeout=timeout, skip_parameter_relation_errors=skip_parameter_relation_errors)

    log_result("Parameter has been successfully set!")


@log_input_and_output
def set_parameter_for_dist_names_via_delta_recommissioning(dist_names, parameter, value):
    """
    Sets the same parameter for multiple dist names on commissioned BTS via BTS delta recommissioning procedure.
    :param dist_names: Dist names to Manage Object with desired parameter.
    :type dist_names: list
    :param parameter: Parameter abbreviation that user wants to change.
    :type parameter: str
    :param value: new value of parameter to be set via BTS delta recommissioning.
    :type value: str
    """
    delta = DeltaOperator()

    for dist_name in dist_names:
        delta.add_parameter_to_delta(dist_name=dist_name, parameter=parameter, value=value)

    delta.perform_delta_recommissioning()
    log_result("Parameters has been successfully set!")


@log_input_and_output
def set_parameters_for_dist_names_via_delta_recommissioning(objects_dict, skip_parameter_relation_errors=False,
                                                            timeout=60):
    """
    Sets custom parameters for dist names on commissioned BTS via BTS delta recommissioning procedure.

    :param objects_dict: Nested dict containing Dist name to Manage Object as key and desired parameters dict as item,
                        e.g. {
                                {'MRBTS-50521/NRBTS-50521/NRCELL-1':{'pMax': '370', 'chbw': '30 MHz'}}
                                {'MRBTS-50521/NRBTS-50521/NRCELL-3':{'chbw': '10 MHz'}}
                             }

    :type objects_dict: dict(dict)
    :param skip_parameter_relation_errors: Skip parameter relation errors.
    :type skip_parameter_relation_errors: boolean
    :param timeout: time in seconds to wait for successful recommissioning
    :type timeout: int
    """
    delta = DeltaOperator()

    for dist_name, params in objects_dict.items():
        log_step(f"Setting parameters for {dist_name} via delta commissioning on BTS: {params}")
        delta.add_parameters_to_delta(dist_name=dist_name, delta_dict=params)

    try:
        delta.perform_delta_recommissioning(timeout=timeout,
                                            skip_parameter_relation_errors=skip_parameter_relation_errors)
    finally:
        delta.remove_delta()

    log_result("Parameters for provided dist names has been successfully set!")


@log_input_and_output
def set_parameters_for_dist_names_via_delta_recommissioning_in_separate_process(objects_dict,
                                                                                skip_parameter_relation_errors=False,
                                                                                should_activate=True,
                                                                                timeout=60):
    """
    Sets custom parameters for dist names on commissioned BTS via BTS delta recommissioning procedure in separate
    process.

    :param objects_dict: Nested dict containing Dist name to Manage Object as key and desired parameters dict as item,
                    e.g. {
                            {'MRBTS-50521/NRBTS-50521/NRCELL-1':{'pMax': '370', 'chbw': '30 MHz'}}
                            {'MRBTS-50521/NRBTS-50521/NRCELL-3':{'chbw': '10 MHz'}}
                         }

    :type objects_dict: dict(dict)
    :param skip_parameter_relation_errors: Skip parameter relation errors.
    :type skip_parameter_relation_errors: boolean
    :param should_activate: Should automatically activate plan.
    :type should_activate: boolean
    :param timeout: time in seconds to wait for successful recommissioning
    :type timeout: int
    """
    delta = DeltaOperator()

    for dist_name, params in objects_dict.items():
        log_step(f"Setting parameters for {dist_name} via delta commissioning on BTS: {params} in separate process")
        delta.add_parameters_to_delta(dist_name=dist_name, delta_dict=params)

    try:
        task = delta.perform_delta_recommissioning_in_separate_process(
            timeout=timeout,
            should_activate=should_activate,
            skip_parameter_relation_errors=skip_parameter_relation_errors
        )
    finally:
        delta.remove_delta()

    log_result("Delta recommissioning has been started in separate process!")

    return task


@log_input_and_output
def create_rmod_object(dist_name, prodCodePlanned_value):
    """
    Creates new RMOD object in plan via BTS delta recommissioning procedure.

    :param dist_name: Dist name to Managed Object.
    :type dist_name: str
    :param prodCodePlanned_value: prodCodePlanned parameter value to be set via BTS delta recommissioning.
    :type prodCodePlanned_value: str
    """
    radio_params = {"actPimCancellation": "False",
                    "actSharedRUIndControl": "False",
                    "actSnapshotCollection": "False",
                    "legacyWideCarrierMode": "False",
                    "pimCancellingEnabled": "True",
                    "actParExpansionOff": "False",
                    "energySavingMode": "NORMAL"
                    }
    delta = DeltaOperator()
    delta.add_moc_to_delta(dist_name=dist_name)
    delta.add_parameters_to_delta(dist_name=dist_name, delta_dict=radio_params)

    delta.add_parameter_to_delta(dist_name=dist_name, parameter="prodCodePlanned", value=prodCodePlanned_value)
    delta.perform_delta_recommissioning(should_activate=True, skip_parameter_relation_errors=True)
    delta.remove_delta()
    log_result("RMOD has been succesfully created!")


