@log_input_and_output
def perform_online_delta_commissioning(path_to_delta, bts_type='GNB', use_proxy=False, timeout=180):
    """
    Performs online delta commissioning on BTS. If delta commissioning fails due to not updatable parameters
    or object already existing, it will exclude problematic parameters and objects, and try to perform delta
    commissioning again. If delta commissioning fails due to other errors, it will raise
    AdminApiProcedureFailureException.
    :param path_to_delta: path to delta file
    :type path_to_delta: str
    :param bts_type: BTS type, e.g. 'GNB', 'ENB'
    :type bts_type: str
    :param use_proxy: connect to remote ENB via VM proxy when True and bts_type='ENB',
                      when False and bts_type='ENB' connect to ENB SA
    :type use_proxy: bool
    :param timeout: time in seconds to wait for successful recommissioning, e.g. 180, defaults to 180
    :type timeout: int, str
    """
    delta = DeltaOperator(bts_type=bts_type, use_proxy=use_proxy)
    delta.load_delta_and_inject_changes(delta=path_to_delta)

    try:
        delta.perform_delta_recommissioning(should_activate=True, skip_parameter_relation_errors=True, timeout=timeout)
    except AdminApiProcedureFailureException as ex:
        wrong_objects = eval(ex.message.split("Status reached:")[1].split(". Error")[0].strip())
        not_updatable_params = set([param["parameter"] for param in wrong_objects
                                    if param["error"][0] in ['parameter cannot be updated',
                                                             'missing NIDD definition for parameter']])
        not_updatable_objects = set([obj["distName"] for obj in wrong_objects
                                     if obj["error"][0] == 'object cannot be updated'])
        object_already_existing = set([obj["distName"] for obj in wrong_objects
                                       if obj["error"][0] == 'object already exists'])
        delta.reload_delta()
        delta.load_delta_and_inject_changes(delta=path_to_delta, not_updatable_params=not_updatable_params,
                                            object_already_existing=object_already_existing,
                                            not_updatable_objects=not_updatable_objects)

        delta.perform_delta_recommissioning(should_activate=True, skip_parameter_relation_errors=True, timeout=timeout)
    finally:
        delta.remove_delta()

    log_result("Delta has been successfully commissioned!")
